arguments.new_password:
{%- set raw = (uuid() ~ uuid()).replace("-", "") | list -%}
{%- set special_chars = "!@#$%^&*?" | list -%}
{%- set digits_all = "0123456789" | list -%}
{%- set uppercase = [] -%}
{%- set lowercase = [] -%}
{%- set digits = [] -%}

{# Collect characters manually #}
{%- for c in raw -%}
  {%- if c in ['A','B','C','D','E','F'] and uppercase|length < vars.upper_count -%}
    {%- set _ = uppercase.append(c) -%}
  {%- elif c in ['a','b','c','d','e','f'] and lowercase|length < vars.lower_count -%}
    {%- set _ = lowercase.append(c) -%}
  {%- elif c in digits_all and digits|length < vars.digit_count -%}
    {%- set _ = digits.append(c) -%}
  {%- endif -%}
  {%- if uppercase|length == vars.upper_count and lowercase|length == vars.lower_count and digits|length == vars.digit_count -%}
    {%- break -%}
  {%- endif -%}
{%- endfor -%}

{# Pad if any character class is short #}
{%- if uppercase|length < vars.upper_count -%}
  {%- set _ = uppercase.extend(['A'] * (vars.upper_count - uppercase|length)) -%}
{%- endif -%}
{%- if lowercase|length < vars.lower_count -%}
  {%- set _ = lowercase.extend(['a'] * (vars.lower_count - lowercase|length)) -%}
{%- endif -%}
{%- if digits|length < vars.digit_count -%}
  {%- set _ = digits.extend(['0'] * (vars.digit_count - digits|length)) -%}
{%- endif -%}

{# Pick 2 random specials #}
{%- set specials = (special_chars | shuffle)[:vars.special_count] -%}

{# Combine and shuffle all characters #}
{%- set password_chars = (uppercase + lowercase + digits + specials) | shuffle -%}
{{- password_chars | join('') -}}

